public static IReadOnlyList<InstrumentComponents.Drivers.IDriverFactory> SyncFactories(IScpiConnector connector) { var profiles = Create(); return new InstrumentComponents.Drivers.IDriverFactory[] {
new ScpiFactory(profiles[0], "scpi", connector, new InstrumentComponents.Drivers.MatchRule[] { new InstrumentComponents.Drivers.ExactIdentityRule("scpi", "Synthetic", "All") }),
}; }
public static IReadOnlyList<InstrumentComponents.Drivers.IDriverFactory> NativeFactories(IAsyncScpiConnector connector) { var profiles = Create(); return new InstrumentComponents.Drivers.IDriverFactory[] {
new AsyncScpiFactory(profiles[0], "scpi", connector, new InstrumentComponents.Drivers.MatchRule[] { new InstrumentComponents.Drivers.ExactIdentityRule("scpi", "Synthetic", "All") }),
}; }
public static IReadOnlyList<InstrumentComponents.Drivers.IDriverFactory> CombinedFactories(IScpiConnector connector, IAsyncScpiConnector nativeConnector) { var profiles = Create(); return new InstrumentComponents.Drivers.IDriverFactory[] {
new ScpiFactory(profiles[0], "scpi", connector, new InstrumentComponents.Drivers.MatchRule[] { new InstrumentComponents.Drivers.ExactIdentityRule("scpi", "Synthetic", "All") }, nativeConnector),
}; }
